root=Path(__file__).resolve().parents[1];p=root/'src/lib/contenido-bases.js';s=p.read_text(encoding='utf-8');start='// R14: figuras y superficies.';end='// FIN R14'
if start in s:s=s[:s.index(start)]+s[s.index(end)+len(end):]
code=start+'\nconst FIGURAS_R14 = '+json.dumps(U,ensure_ascii=False,indent=2)+""";
for (const unidad of FIGURAS_R14) {
 const indice = UNIDADES_BASES.findIndex(u => u.id === (unidad.antes_de || unidad.despues_de));
 if (indice < 0) throw new Error('Falta el paso de referencia de ' + unidad.id);
 UNIDADES_BASES.splice(indice + (unidad.antes_de ? 0 : 1), 0, unidad);
}
"""+'const APOYOS_R14 = '+json.dumps(APOYOS,ensure_ascii=False)+';\nfor (const [id, visual] of Object.entries(APOYOS_R14)) { UNIDADES_BASES.find(u => u.id === id).visual = visual; }\n'+end+'\n\n';i=s.index('export const TEMAS_BASES');p.write_text(s[:i]+code+s[i:],encoding='utf-8');print(len(U),'unidades;',len(U)*6,'actividades')
